const express = require('express');
const path = require('path');
const { Server } = require('@tus/server');
const { S3Store } = require('@tus/s3-store');
const { S3Client } = require('@aws-sdk/client-s3');
const { verifySessionCookie } = require('../auth');

const app = express();

const s3Tus = new Server({
  path: '/tus/assets',
  datastore: new S3Store({ s3ClientConfig: { bucket: 'user-public-assets' } }),
  namingFunction: (req) => {
    const filename = req.headers['x-asset-filename'] || `${Date.now()}.bin`;
    // Enforce ownership sandbox per authenticated user session
    return `avatars/${req.session.userId}/${path.basename(filename)}`;
  }
});

app.use('/tus/assets', verifySessionCookie, (req, res) => {
  s3Tus.handle(req, res);
});
